/* ============================================================
   PATCH v1.4.10 — новый вид «🧪 Дерево» + оригинальный компакт
   ============================================================ */

.tasks-grid[data-compact="1"]:not([data-view="tree"]) .task-card-inline-timeline {
    display: none !important;
}
.tasks-grid[data-view="tree"] .task-card-inline-timeline {
    display: block !important;
}

#tskViewSeg button[data-view="tree"] {
    color: var(--trk-desc);
}
#tskViewSeg button[data-view="tree"]:hover {
    color: var(--trk-accent);
}
#tskViewSeg button[data-view="tree"].active {
    background: rgba(155,89,182,0.20) !important;
    border-color: #9b59b6 !important;
    color: #c39bd3 !important;
}
body.trk-theme-light #tskViewSeg button[data-view="tree"].active {
    background: rgba(155,89,182,0.15) !important;
    color: #6c3483 !important;
}

